,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_english_name VARCHAR2(4000);',
'    l_urdu_name    CLOB;',
'BEGIN',
'    l_english_name := :APP_USER;',
'',
'    BEGIN',
'        l_urdu_name :=',
'            apex_ai.generate(',
'                p_prompt =>',
'                    ''Convert this person name into natural Urdu script. '' ||',
'                    ''Return ONLY the Urdu name, without quotes or explanation. '' ||',
'                    ''Name: '' || l_english_name,',
'                p_service_static_id => ''GoogleAi''',
'            );',
'',
'        -- Gemini successful',
'        IF l_urdu_name IS NOT NULL THEN',
'            :G_URDU_NAME := TRIM(l_urdu_name);',
'            :P1_USER_URDU_NAME := TRIM(l_urdu_name);',
'        ELSE',
'            -- Empty response: use original name',
'            :G_URDU_NAME := l_english_name;',
'            :P1_USER_URDU_NAME := l_english_name;',
'        END IF;',
'',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'',
'            -- Gemini error / quota exceeded / any AI error',
'            :G_URDU_NAME := l_english_name;',
'            :P1_USER_URDU_NAME := l_english_name;',
'',
'    END;',
'',
'END;',
'',
'',
'',
'',
